const incoming=$json.body??$json;
const batchId=incoming.batchId||incoming.jobId||('batch-'+Date.now());
const productName=incoming.productName||incoming.product?.name||'Товар';
const productUtp=incoming.productUtp||incoming.product?.utp||'';
const productRules=incoming.productRules||incoming.product?.rules||'';
const brief=String(incoming.brief||'').trim();
const style=String(incoming.style||'UGC').trim();
const character=incoming.character||null;
const urlOf=x=>typeof x==='string'?x:(x?.url||'');
const productRefs=(incoming.productMedia||incoming.media||incoming.product?.media||[]).map(urlOf);
const avatarRefs=(incoming.avatarReferences||character?.media||[]).map(urlOf);
const references=[...new Set([...productRefs,...avatarRefs].filter(x=>/^https?:\/\//i.test(x)))].slice(0,9);
const hasReferences=references.length>0;
const endpoint='https://api.higgsfield.ai/bytedance/seedance-2.0/'+(hasReferences?'reference-to-video':'text-to-video');
const prompt=[
  'Create a photorealistic vertical 9:16 product advertising shot.',
  'Product: '+productName+'.',
  brief?('Creative brief: '+brief):'',
  style?('Visual style: '+style+'.'):'',
  productUtp?('Product information supplied by seller: '+productUtp):'',
  productRules?('Strict product constraints: '+productRules):'',
  character?('Use the same presenter identity from the supplied avatar reference images. Presenter description: '+[character.name,character.look].filter(Boolean).join(', ')+'.'):'',
  'Preserve the exact real product shape, proportions, color, construction and visible details from all product references.',
  'Do not invent accessories, features, packaging, labels, materials, claims or product properties.',
  'Natural human motion, believable hands and product handling, premium commercial lighting, realistic skin and textures.',
  'No artificial text overlays, subtitles or captions in the generated footage.',
  'Strong visual hook in the first second, clear product focus, smartphone-friendly composition.'
].filter(Boolean).join('\n');
return [{json:{
  batchId,productName,productId:incoming.productId||null,prompt,references,
  endpoint,duration:5,resolution:'720p',aspectRatio:'9:16',
  provider:'higgsfield',model:'bytedance/seedance-2.0/'+(hasReferences?'reference-to-video':'text-to-video')
}}];

const submit=$json;
const prep=$('Подготовить генерацию').item.json;
const requestId=submit.request_id||submit.id;
if(!requestId) throw new Error('Higgsfield не вернул request_id: '+JSON.stringify(submit));
const statusUrl=submit.status_url||('https://api.higgsfield.ai/requests/'+requestId+'/status');
return [{json:{...prep,requestId,statusUrl,hfStatus:String(submit.status||'queued').toLowerCase()}}];

const status=$json;
const submitted=$('Запомнить request_id').item.json;
const rawState=String(status.status||status.state||status.request_status||'').toLowerCase();
const videoUrl=status.video?.url||status.output?.video?.url||status.result?.video?.url||status.data?.video?.url||null;
const done=!!videoUrl||['completed','succeeded','success','done'].includes(rawState);
const failed=['failed','error','canceled','cancelled','nsfw','ip_detected'].includes(rawState);
return [{json:{...submitted,hfStatus:rawState||submitted.hfStatus,videoUrl,done,failed,statusPayload:status}}];
